class Solution {
  public int maxFrequency(int[] nums, int k, int numOperations) {
    int max = 0;
    for (int x : nums) max = Math.max(max, x);
    int limit = max + k + 1;
    int[] prefix = new int[limit + 2]; // prefix[v + 1] = number of elements <= v
    int[] count = new int[limit + 1];
    for (int x : nums) count[x]++;
    for (int v = 0; v <= limit; v++) prefix[v + 1] = prefix[v] + count[v];
    int best = 0;
    for (int v = 0; v <= limit; v++) {
      int lo = Math.max(0, v - k), hi = Math.min(limit, v + k);
      int inRange = prefix[hi + 1] - prefix[lo];
      best = Math.max(best, count[v] + Math.min(numOperations, inRange - count[v]));
    }
    return best;
  }
}
